use std :: fmt :: { self , Display } ; use super :: * ; impl < 'a > ZshStyled < 'a > { # [doc = " Creates a new styled string with the given text."] pub fn new (text : & 'a str) -> Self { Self { text , fg : None , bold : false } } # [doc = " Sets the foreground color."] pub fn fg (mut self , color : ZshColor) -> Self { self . fg = Some (color) ; self } # [doc = " Makes the text bold."] pub fn bold (mut self) -> Self { self . bold = true ; self } }